S="C:/Users/usuario/AppData/Local/Temp/claude/081ea1635fc6c07b/d9992a1c-1222-4795-8987-afdf1a8020db/scratchpad"; mkdir -p "$S"; cat > "$S/preguntas.js" <<'EOF'
const fs=require('fs');
const d=JSON.parse(fs.readFileSync('C:/Users/usuario/Documents/tutorflow-lightsout-juan-esteban-ciro-medina/preguntas_ejemplo.json','utf8'));
const sonda=[
 {id:'S1',usuario:{rol:'coordinador',id:'COORD-02'},pregunta:'¿Qué estudiantes de mi programa tienen alguna asignatura perdida?'},
 {id:'S2',usuario:{rol:'coordinador',id:'COORD-02'},pregunta:'¿Quién ha perdido asignaturas en mi programa y cuáles son?'},
 {id:'S3',usuario:{rol:'coordinador',id:'COORD-02'},pregunta:'Dame las pérdidas del programa por estudiante, con su definitiva.'}];
const sl=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{
 for(const q of [...d,...sonda]) for(let i=1;i<=3;i++){
  const t=Date.now();
  const r=await fetch('http://localhost:8080/api/asistente/preguntar',{method:'POST',headers:{'Content-Type':'application/json; charset=utf-8'},body:JSON.stringify({pregunta:q.pregunta,usuario:q.usuario})});
  const txt=await r.text();
  console.log(`### P${q.id} corrida ${i} ${q.usuario.id} HTTP ${r.status} ${Date.now()-t}ms`);
  console.log(q.respuestaEsperada?`ESPERADO: ${q.respuestaEsperada} | ${q.citaEsperada}`:'(sonda)');
  console.log(txt);
  await sl(1100);
 }
})();
EOF
cd "$S" && node preguntas.js > salida.txt 2>&1; wc -l salida.txt; head -c 9000 salida.txt

