cd "C:/Users/usuario/AppData/Local/Temp/claude/081ea1635fc6c07b/d9992a1c-1222-4795-8987-afdf1a8020db/scratchpad"; docker run --rm -v tutorflow_auditoria:/a alpine cat /a/auditoria-2026-11-23.jsonl > aud.jsonl; docker compose -f ../../../../../../../Documents/tutorflow-lightsout-juan-esteban-ciro-medina/docker-compose.yml logs api 2>/dev/null | grep -ci "LLM_API_KEY\|api[_-]key\|sk-" ; cat > a.js <<'EOF'
const L=require('fs').readFileSync('aud.jsonl','utf8').trim().split('\n').map(JSON.parse);
const i=L.findIndex(e=>e.pregunta&&e.pregunta.includes('mínima para aprobar una asignatura')&&e.usuario.id==='EST-001');
console.log('total',L.length,'primer evento P1 en',i);
const mine=L.filter(e=>e.timestamp>='2026-11-23T17:1'&&false);
const since=L.slice(i);
console.log('eventos desde P1:',since.length,'(esperado 39 de la corrida de preguntas + 68 de Postman)');
const ks=new Set();L.forEach(e=>Object.keys(e).forEach(k=>ks.add(k)));console.log([...ks].join(','));
for(const e of since.slice(0,39).filter((e,n)=>[0,3,6,9,12,15,18,21,24,27,30,33,36,38].includes(n))) console.log(JSON.stringify({u:e.usuario.id,p:e.pregunta,r:e.resultado,m:e.motivoDenegacion,est:e.estudiantesConsultados,rec:e.recursosConsultados,dat:e.datosConsultados,c:e.citas.length}));
const s=JSON.stringify(L);
console.log('LLM_API_KEY/key mentions:',(s.match(/LLM_API_KEY|api[_-]?key|sk-/gi)||[]).length);
console.log('terceros literales Andrés Martínez/EST-002 en pregunta:',L.filter(e=>/Andr[eé]s Mart[ií]nez|EST-002/.test(e.pregunta||'')).length, 'ejemplo:',(L.find(e=>/TERCERO/.test(e.pregunta||''))||{}).pregunta);
console.log('valores numericos en datosConsultados:',L.filter(e=>e.datosConsultados.some(d=>/\d\.\d/.test(JSON.stringify(d)))).length);
const cnt={};L.forEach(e=>cnt[e.resultado]=(cnt[e.resultado]||0)+1);console.log(cnt);
EOF
