namespace TutorFlow.Api;

public static class ValidadorDeConfiguracion
{
    internal const string PrefijoInvalida = "Configuración inválida";
    internal const string PrefijoIgnorada = "Configuración ignorada";
    private const string SeccionModelos = "Llm:Proveedores";
    private const string PrecioDeEntrada = "PrecioEntradaPorMillon";
    private const string PrecioDeSalida = "PrecioSalidaPorMillon";

    public static IReadOnlyList<string> Validar(IConfiguration configuracion) =>
        [.. ReglasDeError(configuracion)
            .Where(regla => EsInvalido(configuracion, regla))
            .Select(regla => $"{PrefijoInvalida}: {regla.Clave} = \"{ValorDeMensaje.De(configuracion[regla.Clave])}\" ({regla.Texto})")
            .Concat(ValidadorDeCatalogo.Validar(configuracion))];

    internal static IReadOnlyList<string> Advertencias(IConfiguration configuracion) =>
        [.. ReglaDeConfiguracion.ConAdvertencia
            .Where(regla => EsInvalido(configuracion, regla))
            .Select(regla => $"{PrefijoIgnorada}: {regla.Clave} = \"{ValorDeMensaje.De(configuracion[regla.Clave])}\" ({regla.Texto}); se usa {regla.Defecto}")];

    internal static IReadOnlyList<string> ClavesParaAnular(IConfiguration configuracion) =>
        [.. ReglasDeError(configuracion).Concat(ReglaDeConfiguracion.ConAdvertencia)
            .Where(regla => EstaEnBlanco(configuracion[regla.Clave]) || (regla.Defecto is not null && EsInvalido(configuracion, regla)))
            .Select(regla => regla.Clave)];

    private static IEnumerable<ReglaDeConfiguracion> ReglasDeError(IConfiguration configuracion) =>
        ReglaDeConfiguracion.Todas.Concat(ClavesDePrecioPorModelo(configuracion).Select(ReglaDeConfiguracion.Precio));

    private static IEnumerable<string> ClavesDePrecioPorModelo(IConfiguration configuracion) =>
        configuracion.GetSection(SeccionModelos).GetChildren()
            .SelectMany(proveedor => proveedor.GetSection("Modelos").GetChildren())
            .SelectMany(modelo => new[] { $"{modelo.Path}:{PrecioDeEntrada}", $"{modelo.Path}:{PrecioDeSalida}" });

    private static bool EsInvalido(IConfiguration configuracion, ReglaDeConfiguracion regla)
    {
        var valor = configuracion[regla.Clave];
        return !string.IsNullOrWhiteSpace(valor) && !regla.Cumple(valor);
    }

    private static bool EstaEnBlanco(string? valor) => valor is not null && string.IsNullOrWhiteSpace(valor);
}
using System.Globalization;
using System.Text.RegularExpressions;
using TutorFlow.Core;

namespace TutorFlow.Api;

internal enum TipoDeValor
{
    Entero,
    Decimal,
    Booleano
}

internal sealed partial record ReglaDeConfiguracion(
    string Clave,
    TipoDeValor Tipo,
    decimal Minimo,
    decimal Maximo,
    bool MinimoExclusivo,
    string Texto,
    string? Defecto = null)
{
    private const decimal MaximoPrecio = 1000m;

    public static IReadOnlyList<ReglaDeConfiguracion> Todas { get; } =
    [
        Entero("Conocimiento:RelevanciaMinima", 1, 10),
        Entero("Conocimiento:ApoyoMinimoRespaldo", 1, 10),
        Entero("Limites:MaximoCaracteresPregunta", 1, 1000),
        Entero("Limites:MaximoBytesCuerpo", 1024, 16384),
        Entero("Limites:PreguntasPorMinutoPorIp", 1, 10000),
        Entero("Limites:MaximoSeccionesRecuperadas", 1, 6),
        Entero("Limites:MaximoTokensSalida", 1, 2000),
        Entero("Limites:MaximoInvocacionesHerramientas", 1, 4),
        Entero("Limites:TimeoutLlmSegundos", 1, 60),
        Entero("Limites:PresupuestoApiAcademicaSegundos", 1, 30),
        new("Limites:PresupuestoDiarioUsd", TipoDeValor.Decimal, 0m, MaximoPrecio, true, "decimal mayor que 0 y hasta 1000"),
        Entero("Limites:MaximoIdentidadesPorIp", 1, 100),
        Entero("Limites:VentanaIdentidadesMinutos", 1, 1440),
        new("Limites:BloquearMultiplesIdentidades", TipoDeValor.Booleano, 0m, 0m, false, "true o false"),
        Precio("LLM_PRECIO_ENTRADA"),
        Precio("LLM_PRECIO_SALIDA")
    ];

    public static IReadOnlyList<ReglaDeConfiguracion> ConAdvertencia { get; } =
    [
        Reserva("Llm:ReservaPorPeticionUsd", "el estimado de 8000 tokens de entrada y 2000 de salida"),
        Reserva("Llm:ReservaSinPrecioUsd", "0.01")
    ];

    public static ReglaDeConfiguracion Precio(string clave) =>
        new(clave, TipoDeValor.Decimal, 0m, MaximoPrecio, false, "decimal de 0 a 1000");

    public bool Cumple(string valor) => Tipo switch
    {
        TipoDeValor.Booleano => bool.TryParse(valor, out _) && valor.Trim() == valor,
        TipoDeValor.Entero => FormatoEntero().IsMatch(valor) && EnRango(valor),
        _ => FormatoDecimal().IsMatch(valor) && EnRango(valor)
    };

    private static ReglaDeConfiguracion Entero(string clave, int minimo, int maximo) =>
        new(clave, TipoDeValor.Entero, minimo, maximo, false, $"entero de {minimo} a {maximo}");

    private static ReglaDeConfiguracion Reserva(string clave, string defecto) =>
        new(clave, TipoDeValor.Decimal, 0m, decimal.MaxValue, true, "decimal mayor que 0", defecto);

    private bool EnRango(string valor) =>
        decimal.TryParse(valor, NumberStyles.Float, CultureInfo.InvariantCulture, out var numero)
        && (MinimoExclusivo ? numero > Minimo : numero >= Minimo)
        && numero <= Maximo;

    [GeneratedRegex(@"^-?[0-9]+\z", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex FormatoEntero();

    [GeneratedRegex(@"^-?[0-9]+(\.[0-9]+)?\z", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex FormatoDecimal();
}
using TutorFlow.Infrastructure.Configuracion;

namespace TutorFlow.Api;

internal sealed partial class ValidacionDeArranque : IHostedLifecycleService
{
    private static readonly string[] VariablesDePrecio = ["LLM_PRECIO_ENTRADA", "LLM_PRECIO_SALIDA"];

    private readonly IConfiguration _configuracion;
    private readonly IVariablesEntorno _variables;
    private readonly ILogger _logger;

    public ValidacionDeArranque(IConfiguration configuracion, IVariablesEntorno variables, ILoggerFactory fabricaDeLogs)
    {
        _configuracion = configuracion;
        _variables = variables;
        _logger = fabricaDeLogs.CreateLogger("TutorFlow.Configuracion");
    }

    public Task StartingAsync(CancellationToken cancellationToken)
    {
        var efectiva = ConEntorno();
        var errores = ValidadorDeConfiguracion.Validar(efectiva);
        if (errores.Count > 0)
        {
            throw new InvalidOperationException(string.Join("\n", errores));
        }

        foreach (var advertencia in ValidadorDeConfiguracion.Advertencias(efectiva))
        {
            RegistrarAdvertencia(_logger, advertencia);
        }

        AnularValoresIgnorados(ValidadorDeConfiguracion.ClavesParaAnular(efectiva));
        return Task.CompletedTask;
    }

    public Task StartAsync(CancellationToken cancellationToken) => Task.CompletedTask;

    public Task StartedAsync(CancellationToken cancellationToken) => Task.CompletedTask;

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;

    public Task StoppingAsync(CancellationToken cancellationToken) => Task.CompletedTask;

    public Task StoppedAsync(CancellationToken cancellationToken) => Task.CompletedTask;

    private IConfiguration ConEntorno()
    {
        var delEntorno = VariablesDePrecio
            .Select(nombre => new KeyValuePair<string, string?>(nombre, _variables.Leer(nombre)))
            .Where(par => par.Value is not null);
        return new ConfigurationBuilder().AddConfiguration(_configuracion).AddInMemoryCollection(delEntorno).Build();
    }

    private void AnularValoresIgnorados(IEnumerable<string> claves)
    {
        if (_configuracion is IConfigurationBuilder constructor)
        {
            constructor.AddInMemoryCollection(claves.Select(clave => new KeyValuePair<string, string?>(clave, null)));
        }
    }

    [LoggerMessage(Level = LogLevel.Warning, Message = "{Mensaje}")]
    internal static partial void RegistrarAdvertencia(ILogger logger, string mensaje);
}
namespace TutorFlow.Api;

internal static class ValorDeMensaje
{
    private const int LongitudMaxima = 64;
    private const string PuntosSuspensivos = "…";

    public static string De(string? valor)
    {
        var escapado = string.Concat((valor ?? string.Empty).Select(Escapar));
        return escapado.Length <= LongitudMaxima ? escapado : escapado[..Corte(escapado)] + PuntosSuspensivos;
    }

    private static int Corte(string escapado) =>
        char.IsHighSurrogate(escapado[LongitudMaxima - 1]) ? LongitudMaxima - 1 : LongitudMaxima;

    private static string Escapar(char caracter) => caracter switch
    {
        '"' => "\\\"",
        '\\' => "\\\\",
        '\n' => "\\n",
        '\r' => "\\r",
        '\t' => "\\t",
        _ when char.IsControl(caracter) => $"\\u{(int)caracter:X4}",
        _ => caracter.ToString()
    };
}
using System.Text.RegularExpressions;
using TutorFlow.Core;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Api;

internal static partial class ValidadorDeCatalogo
{
    public const string SeccionAsignaturas = "Autorizacion:Asignaturas";
    public const string SeccionListaDeCodigos = "Autorizacion:CodigosAsignatura";
    private const string ReglaFormato = @"formato ^[A-Z]{2,4}-[0-9]{3}\z";

    private sealed record Entrada(string Indice, string? Codigo, string? Nombre)
    {
        public string ClaveDeCodigo => $"{SeccionAsignaturas}:{Indice}:Codigo";

        public string ClaveDeNombre => $"{SeccionAsignaturas}:{Indice}:Nombre";
    }

    public static IEnumerable<string> Validar(IConfiguration configuracion)
    {
        var entradas = configuracion.GetSection(SeccionAsignaturas).GetChildren()
            .Select(hijo => new Entrada(hijo.Key, hijo["Codigo"], hijo["Nombre"]))
            .ToList();
        var delCatalogo = entradas.Count == 0
            ? [Linea(SeccionAsignaturas, string.Empty, "catálogo vacío")]
            : entradas.SelectMany(entrada => LineasDe(entrada, entradas));
        return delCatalogo.Concat(LineasDeLaLista(configuracion, entradas));
    }

    private static IEnumerable<string> LineasDe(Entrada entrada, List<Entrada> entradas)
    {
        var anteriores = entradas.Take(entradas.IndexOf(entrada)).ToList();
        var codigoRepetido = anteriores.FirstOrDefault(otra => !string.IsNullOrEmpty(entrada.Codigo) && otra.Codigo == entrada.Codigo);
        var nombreRepetido = anteriores.FirstOrDefault(otra => !EstaVacio(entrada.Nombre) && Normalizado(otra.Nombre) == Normalizado(entrada.Nombre));
        return Lineas(
            (!CumpleFormato(entrada.Codigo), entrada.ClaveDeCodigo, entrada.Codigo, ReglaFormato),
            (codigoRepetido is not null, entrada.ClaveDeCodigo, entrada.Codigo, $"código duplicado de {codigoRepetido?.ClaveDeCodigo}"),
            (EstaVacio(entrada.Nombre), entrada.ClaveDeNombre, entrada.Nombre, "nombre vacío"),
            (nombreRepetido is not null, entrada.ClaveDeNombre, entrada.Nombre, $"nombre duplicado de {nombreRepetido?.ClaveDeNombre}"));
    }

    private static IEnumerable<string> LineasDeLaLista(IConfiguration configuracion, List<Entrada> entradas)
    {
        var codigos = configuracion.GetSection(SeccionListaDeCodigos).GetChildren().Select(hijo => (hijo.Path, hijo.Value)).ToList();
        return codigos.SelectMany((codigo, posicion) =>
        {
            var formato = CumpleFormato(codigo.Value);
            var repetido = codigos.Take(posicion).FirstOrDefault(otro => otro.Value == codigo.Value);
            return Lineas(
                (!formato, codigo.Path, codigo.Value, ReglaFormato),
                (formato && repetido.Path is not null, codigo.Path, codigo.Value, $"código duplicado de {repetido.Path}"),
                (formato && entradas.All(entrada => entrada.Codigo != codigo.Value), codigo.Path, codigo.Value, $"no está en {SeccionAsignaturas}"));
        });
    }

    private static IEnumerable<string> Lineas(params (bool Falla, string Clave, string? Valor, string Regla)[] reglas) =>
        reglas.Where(regla => regla.Falla).Select(regla => Linea(regla.Clave, regla.Valor, regla.Regla));

    private static string Linea(string clave, string? valor, string regla) =>
        $"{ValidadorDeConfiguracion.PrefijoInvalida}: {clave} = \"{ValorDeMensaje.De(valor)}\" ({regla})";

    private static bool EstaVacio(string? texto) => string.IsNullOrWhiteSpace(texto);

    private static string Normalizado(string? texto) => NormalizadorTexto.Normalizar(texto ?? string.Empty);

    private static bool CumpleFormato(string? codigo) => codigo is not null && FormatoDeCodigo().IsMatch(codigo);

    [GeneratedRegex(@"^[A-Z]{2,4}-[0-9]{3}\z", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex FormatoDeCodigo();
}

