using System.Text.RegularExpressions;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

public static partial class ReferenciasEscritas
{
    private const char Marca = '';
    private const int PalabrasMinimasPorOracion = 3;
    private const string DocumentoDerogado = "reglamento_academico_2023.md";
    private const string FinDePalabra = @"(?![\p{L}\p{N}_-])";
    private const string Parada = "(?:según|segun|ver|consulta|en|de|del|con|a|al|el|la|los|las)";
    private const string PalabraIzquierda = @"(?:(?!" + Parada + FinDePalabra + @")[\p{L}_-]+ +)";
    private const string Numero = @"\d+(?:\.\d+)*";
    private const string Documento =
        @"(?<doc>(?<![\p{L}\p{N}_-])(?:" + PalabraIzquierda + @"{1,3}\d+\.md|[\p{L}\p{N}_-]+\.md)" + FinDePalabra + ")";
    private const string Seccion =
        @"(?<sec>(?<![\p{L}\p{N}])(?:secci[oó]n(?:es)?|art[ií]culos?|art\.?|§)\s*" + Numero + @"(?:\s*(?:,|y|e)\s*" + Numero + ")*)";
    private const string Conector =
        @"(?:(?<![\p{L}\p{N}_-])(?:(?:según|segun|de\s+acuerdo\s+con|conforme\s+al?|ver|consulta|se\s+respaldan?\s+en|en|de|del)"
        + @"(?:\s+(?:el|la|los|las))?|(?:el|la|los|las))\s+)?";
    private const string ConectorHaciaDocumento = @"\s+(?:de\s+la|del|de|en\s+el|en)\s+";
    private const string PatronReferencia =
        Conector + "(?:" + Seccion + ConectorHaciaDocumento + Documento
        + "|" + Documento + @"\s*[·,:-]\s*" + Seccion
        + "|" + Documento + ")";

    private static readonly TimeSpan LimiteRegex = TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos);

    private static readonly (Regex Patron, string Reemplazo)[] ReglasDeSignos =
    [
        (new Regex(@"[\(\[][\s·,;:]*[\)\]]", RegexOptions.CultureInvariant, LimiteRegex), string.Empty),
        (new Regex(@" {2,}", RegexOptions.CultureInvariant, LimiteRegex), " "),
        (new Regex(@" +(?=[.,;:!?)])", RegexOptions.CultureInvariant, LimiteRegex), string.Empty),
        (new Regex(@"(?<!\.)\.\.(?!\.)", RegexOptions.CultureInvariant, LimiteRegex), "."),
        (new Regex(@"[,;:]\.", RegexOptions.CultureInvariant, LimiteRegex), "."),
        (new Regex(@",,", RegexOptions.CultureInvariant, LimiteRegex), ",")
    ];

    public static string Limpiar(string respuesta, IReadOnlyList<Cita> citas)
    {
        var marcada = Referencia().Replace(respuesta, coincidencia => EsValida(coincidencia, citas) ? coincidencia.Value : Marca.ToString());
        return marcada.Contains(Marca, StringComparison.Ordinal) ? Depurar(marcada) : respuesta;
    }

    public static bool TienePalabras(string texto) => PalabraDeLetras().IsMatch(texto);

    private static string Depurar(string marcada) =>
        string.Concat(CorteDeOracion().Split(marcada).Select(DepurarOracion)).Trim();

    private static string DepurarOracion(string oracion) =>
        oracion.Contains(Marca, StringComparison.Ordinal)
            ? DepurarOracionConReferenciaEliminada(oracion.Replace(Marca.ToString(), string.Empty, StringComparison.Ordinal))
            : oracion;

    private static string DepurarOracionConReferenciaEliminada(string oracion) =>
        Palabras(oracion) < PalabrasMinimasPorOracion
            ? string.Empty
            : Capitalizar(ReglasDeSignos.Aggregate(oracion, (texto, regla) => regla.Patron.Replace(texto, regla.Reemplazo)));

    private static int Palabras(string oracion) => PalabraOCifra().Count(oracion);

    private static string Capitalizar(string oracion)
    {
        var inicio = oracion.Length - oracion.TrimStart().Length;
        return inicio < oracion.Length && char.IsLower(oracion[inicio])
            ? string.Concat(oracion.AsSpan(0, inicio), char.ToUpperInvariant(oracion[inicio]).ToString(), oracion.AsSpan(inicio + 1))
            : oracion;
    }

    private static bool EsValida(Match coincidencia, IReadOnlyList<Cita> citas)
    {
        var documento = PlegadoCompatibilidad.Aplicar(coincidencia.Groups["doc"].Value);
        var seccion = coincidencia.Groups["sec"];
        return seccion.Success
            ? NumerosDe(seccion.Value).All(numero => citas.Any(cita => EsCitaDe(cita, documento, numero)))
            : string.Equals(documento, DocumentoDerogado, StringComparison.OrdinalIgnoreCase)
                || citas.Any(cita => MismoDocumento(cita, documento));
    }

    private static IEnumerable<string> NumerosDe(string seccion) =>
        NumeroDeSeccion().Matches(seccion).Select(numero => numero.Value);

    private static bool EsCitaDe(Cita cita, string documento, string numero) =>
        MismoDocumento(cita, documento) && NumeroDeSeccion().Matches(cita.Seccion).LastOrDefault()?.Value == numero;

    private static bool MismoDocumento(Cita cita, string documento) =>
        string.Equals(PlegadoCompatibilidad.Aplicar(cita.Documento), documento, StringComparison.OrdinalIgnoreCase);

    [GeneratedRegex(PatronReferencia, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex Referencia();

    [GeneratedRegex(@"\d+(?:\.\d+)*", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex NumeroDeSeccion();

    [GeneratedRegex(@"\p{L}{2,}", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PalabraDeLetras();

    [GeneratedRegex(@"[\p{L}\p{N}]+", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PalabraOCifra();

    [GeneratedRegex(@"(?<=\n)|(?<=[.!?;])(?=\s|$)", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex CorteDeOracion();
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal sealed record TramoDePersona(string PersonaId, IReadOnlyList<TokenTexto> Tokens);

internal sealed record OracionAnalizada(string Texto, IReadOnlyList<TramoDePersona> Tramos);

internal static partial class TramosDePersonas
{
    private static readonly HashSet<string> PalabrasDelSujetoCoordinado = new(StringComparer.Ordinal) { "y", "e", "id" };

    public static IEnumerable<string> Oraciones(string respuesta) =>
        CorteDeOracion().Split(respuesta).Where(oracion => !string.IsNullOrWhiteSpace(oracion));

    public static IReadOnlyList<OracionAnalizada> DeRespuesta(
        string respuesta,
        Rol rol,
        IReadOnlyCollection<string> idsAutorizados,
        DirectorioAcademico directorio)
    {
        var herencia = new HerenciaEnListas(rol == Rol.Coordinador);
        return [.. SaltoDeLinea().Split(respuesta).SelectMany(linea =>
        {
            var persona = herencia.PersonaHeredada(linea, DetectorTerceros.MencionesDeAutorizados(linea, idsAutorizados, directorio));
            return persona is null
                ? Oraciones(linea).Select(oracion => new OracionAnalizada(oracion, De(oracion, idsAutorizados, directorio)))
                : [new OracionAnalizada(linea, [new TramoDePersona(persona, TokenizadorTexto.Tokenizar(linea))])];
        })];
    }

    public static IReadOnlyList<TramoDePersona> De(
        string oracion,
        IReadOnlyCollection<string> idsAutorizados,
        DirectorioAcademico directorio)
    {
        var menciones = DetectorTerceros.MencionesDeAutorizados(oracion, idsAutorizados, directorio);
        if (menciones.Count == 0)
        {
            return [];
        }

        var tokens = TokenizadorTexto.Tokenizar(oracion);
        var primeraDeCualquiera = menciones[0].Inicio;
        var tramos = menciones.GroupBy(mencion => mencion.Id)
            .Select(grupo => TramoDe(grupo.Key, grupo.First().Inicio, menciones, tokens, primeraDeCualquiera))
            .ToList();
        return Coordinar(tramos, menciones);
    }

    private static TramoDePersona TramoDe(
        string personaId,
        int inicio,
        IReadOnlyList<MencionDeAutorizado> menciones,
        IReadOnlyList<TokenTexto> tokens,
        int primeraDeCualquiera)
    {
        var fin = menciones
            .Where(mencion => mencion.Id != personaId && mencion.Inicio > inicio)
            .Select(mencion => mencion.Inicio)
            .DefaultIfEmpty(int.MaxValue)
            .Min();
        var delTramo = tokens.Where(token => token.Inicio < primeraDeCualquiera || (token.Inicio >= inicio && token.Inicio < fin));
        return new TramoDePersona(personaId, [.. delTramo]);
    }

    private static List<TramoDePersona> Coordinar(List<TramoDePersona> tramos, IReadOnlyList<MencionDeAutorizado> menciones)
    {
        for (var indice = tramos.Count - 2; indice >= 0; indice--)
        {
            if (ComparteElPredicado(tramos[indice], menciones))
            {
                var siguiente = tramos[indice + 1];
                var propios = siguiente.Tokens.Where(token => !EnMencion(token, siguiente.PersonaId, menciones));
                tramos[indice] = tramos[indice] with { Tokens = [.. tramos[indice].Tokens.Union(propios).OrderBy(token => token.Inicio)] };
            }
        }

        return tramos;
    }

    private static bool ComparteElPredicado(TramoDePersona tramo, IReadOnlyList<MencionDeAutorizado> menciones)
    {
        var primera = menciones.First(mencion => mencion.Id == tramo.PersonaId).Inicio;
        return tramo.Tokens
            .Where(token => token.Inicio >= primera && !EnMencion(token, tramo.PersonaId, menciones))
            .All(token => PalabrasDelSujetoCoordinado.Contains(token.Valor));
    }

    private static bool EnMencion(TokenTexto token, string personaId, IReadOnlyList<MencionDeAutorizado> menciones) =>
        menciones.Any(mencion => mencion.Id == personaId && token.Inicio >= mencion.Inicio && token.Inicio < mencion.Fin);

    [GeneratedRegex(@"\r?\n|(?<=[.!?;])(?=\s|$)", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex CorteDeOracion();

    [GeneratedRegex(@"\r?\n", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SaltoDeLinea();

    private sealed partial class HerenciaEnListas(bool activa)
    {
        private string? _encabezado;
        private bool _enBloque;

        public string? PersonaHeredada(string linea, IReadOnlyList<MencionDeAutorizado> menciones)
        {
            if (!activa)
            {
                return null;
            }

            if (string.IsNullOrWhiteSpace(linea) || menciones.Count > 0)
            {
                Reiniciar(menciones.Count > 0 ? menciones[^1].Id : null);
                return null;
            }

            return Continuar(linea);
        }

        private void Reiniciar(string? encabezado)
        {
            _encabezado = encabezado;
            _enBloque = false;
        }

        private string? Continuar(string linea)
        {
            _enBloque = _enBloque || (_encabezado is not null && MarcadorDeLista().IsMatch(linea));
            _encabezado = _enBloque ? _encabezado : null;
            return _encabezado;
        }

        [GeneratedRegex(@"^\s*(?:[-*•]|\d+[.)])\s", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
        private static partial Regex MarcadorDeLista();
    }
}

